34	export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
35	  const user = await currentUser();
36	  if (!user) redirect("/login");
37	  const imp = await impersonating();
38	
39	  const notifications = await db.notification.findMany({
40	    where: { userId: user.id },
41	    orderBy: { createdAt: "desc" },
42	    take: 15,
43	  });
44	
45	  return (
46	    <Shell
47	      nav={nav}
48	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
49	      notifications={notifications.map((n) => ({
50	        id: n.id,
51	        title: n.title,
52	        body: n.body,
53	        href: n.href,
54	        readAt: n.readAt ? n.readAt.toISOString() : null,
55	        createdAt: n.createdAt.toISOString(),
56	      }))}
57	      impersonation={imp ? { adminName: imp.admin.name, targetEmail: imp.target.email } : null}
58	    >
59	      {children}
60	    </Shell>
61	  );
62	}
