1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { PageHeader, EmptyState } from "@/components/ui/primitives";
4	import { DeployWizard } from "@/components/customer/DeployWizard";
5	import { capacitySnapshot } from "@/lib/capacity";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function DeployPage() {
10	  const user = await requireUser();
11	  const [plans, images, sshKeys, nodes, capacity] = await Promise.all([
12	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
13	    db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
14	    db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
15	    db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
16	    capacitySnapshot(),
17	  ]);
18	
19	  return (
20	    <div className="space-y-6">
21	      <PageHeader title="Deploy a server" sub="NVMe-backed KVM virtual machines, live in under two minutes." />
22	      {capacity.nearCapacity && (
23	        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
24	          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
25	          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
26	        </div>
27	      )}
28	      {plans.length === 0 || images.length === 0 ? (
29	        <EmptyState
30	          title="Deployments are temporarily unavailable"
31	          sub="No active plans or images are configured. Please check back soon or contact support."
32	        />
33	      ) : (
34	        <DeployWizard
35	          plans={plans.map((p) => ({
36	            id: p.id,
37	            name: p.name,
38	            cpuCores: p.cpuCores,
39	            ramMB: p.ramMB,
40	            diskGB: p.diskGB,
41	            bandwidthTB: p.bandwidthTB,
42	            priceCents: p.priceCents,
43	            storageTier: p.storageTier,
44	          }))}
45	          images={images.map((o) => ({
46	            id: o.id,
47	            slug: o.slug,
48	            name: o.name,
49	            category: o.category,
50	            family: o.family,
51	            version: o.version,
52	            logo: o.logo,
53	            minRamMB: o.minRamMB,
54	            minDiskGB: o.minDiskGB,
55	            licenseRequired: o.licenseRequired,
56	            featured: o.featured,
57	          }))}
58	          nodes={nodes}
59	          sshKeys={sshKeys.map((k) => ({ id: k.id, name: k.name }))}
60	          isAdmin={user.role === "ADMIN"}
61	          balanceCents={user.balanceCents}
62	        />
63	      )}
64	    </div>
65	  );
66	}
