10	export default async function ServersPage() {
11	  const user = await requireUser();
12	  const servers = await db.server.findMany({
13	    where: { userId: user.id },
14	    include: { plan: true, osTemplate: true, project: true },
15	    orderBy: { createdAt: "desc" },
16	  });
17	
18	  const transitional = servers.some((s) =>
19	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
20	  );
21	
22	  const rows: ServerRow[] = servers.map((s) => ({
23	    id: s.id,
24	    hostname: s.hostname,
25	    status: s.status,
26	    isFree: s.isFree,
27	    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${s.plan.diskGB} GB`,
28	    osName: s.osTemplate.name,
29	    project: s.project ? { name: s.project.name, color: s.project.color } : null,
30	    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
31	    created: s.createdAt.toISOString().slice(0, 10),
32	  }));
33	
34	  return (
35	    <div className="space-y-6">
36	      {transitional && <AutoRefresh />}
37	      <PageHeader title="Servers" sub="All virtual machines on your account.">
