42	
43	      {servers.length === 0 ? (
44	        <EmptyState
45	          title="No servers yet"
46	          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
47	          action={
48	            <Link href="/dashboard/deploy" className="btn-primary">
49	              Deploy your first server
50	            </Link>
51	          }
52	        />
53	      ) : (
54	        <ServersList servers={rows} />
55	      )}
56	    </div>
57	  );
58	}
