1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { registrarConfigured, getDnsHosts } from "@/lib/registrar";
5	import { PageHeader, StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
6	import { DomainSearch } from "@/components/customer/DomainSearch";
7	import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
8	
9	export const dynamic = "force-dynamic";
10	
11	function daysUntil(d: Date): number {
12	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
13	}
14	
15	function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
16	  if (days === null) return "slate";
17	  if (days < 0) return "red";
18	  if (days <= 30) return "amber";
19	  return "green";
20	}
21	
22	function expiryLabel(d: Date | null): string {
23	  if (!d) return "—";
24	  const days = daysUntil(d);
25	  if (days < 0) return `expired ${-days}d ago`;
26	  if (days === 0) return "expires today";
27	  return `in ${days} day${days === 1 ? "" : "s"}`;
28	}
29	
30	const statusDotFor = (s: string) =>
31	  s === "ACTIVE" ? "RUNNING" : s === "PENDING" ? "PENDING" : s === "EXPIRED" ? "SUSPENDED" : "ERROR";
32	
33	export default async function DomainsPage() {
34	  const user = await requireUser();
35	  const configured = registrarConfigured();
36	  const domains = await db.domain.findMany({
37	    where: { userId: user.id },
38	    orderBy: { createdAt: "desc" },
39	  });
40	
41	  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
42	  const recordCounts = new Map<string, number | null>();
43	  if (configured) {
44	    await Promise.all(
45	      domains
46	        .filter((d) => d.status === "ACTIVE")
47	        .map(async (d) => {
48	          try {
49	            const hosts = await getDnsHosts(d.name);
50	            recordCounts.set(d.id, hosts.length);
51	          } catch {
52	            recordCounts.set(d.id, null);
53	          }
54	        })
55	    );
56	  }
57	
58	  const active = domains.filter((d) => d.status === "ACTIVE").length;
59	  const expiringSoon = domains.filter(
60	    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
61	  ).length;
62	
63	  return (
64	    <div className="space-y-6">
65	      <PageHeader title="Domains" sub="Register and manage domains, right next to your servers.">
66	        {configured && (
67	          <Link href="/dashboard/domains/register" className="btn-primary">
68	            Register a domain
69	          </Link>
70	        )}
71	      </PageHeader>
72	
73	      <DomainSearch configured={configured} />
74	
75	      {domains.length > 0 && (
76	        <div className="grid gap-4 sm:grid-cols-3">
77	          <StatCard
78	            label="Domains"
79	            value={String(domains.length)}
80	            icon={
81	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
82	                <circle cx="12" cy="12" r="9" />
83	                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
84	              </svg>
85	            }
86	          />
87	          <StatCard
88	            label="Active"
89	            value={String(active)}
90	            delta={active === domains.length ? "all active" : `${domains.length - active} inactive`}
91	            deltaGood={active === domains.length}
92	          />
93	          <StatCard
94	            label="Expiring soon"
95	            value={String(expiringSoon)}
96	            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
97	            deltaGood={expiringSoon === 0}
98	          />
99	        </div>
100	      )}
101	
102	      {domains.length === 0 ? (
103	        <EmptyState
104	          title="No domains yet"
105	          sub={
106	            configured
107	              ? "Search above for an available name — you can register and point it at any of your servers in minutes."
108	              : "Domain registration lights up once the registrar integration is configured. Your registered domains will appear here."
109	          }
110	          action={
111	            configured ? (
112	              <Link href="/dashboard/domains/register" className="btn-primary">
113	                Register your first domain
114	              </Link>
115	            ) : undefined
116	          }
117	        />
118	      ) : (
119	        <div className="card p-0">
120	          <div className="flex items-center justify-between px-5 pt-5">
121	            <p className="section-label">Your domains</p>
122	            <span className="text-xs text-slate-500">{domains.length} total</span>
123	          </div>
124	
125	          {/* Card grid on small screens, table on large */}
126	          <div className="grid gap-3 p-5 lg:hidden">
127	            {domains.map((d) => {
128	              const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
129	              const count = recordCounts.get(d.id);
130	              return (
131	                <Link
132	                  key={d.id}
133	                  href={`/dashboard/domains/${d.id}`}
134	                  className="card card-hover block p-4"
135	                >
136	                  <div className="flex items-center justify-between gap-2">
137	                    <span className="truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
138	                    <StatusDot status={statusDotFor(d.status)} label={d.status} />
139	                  </div>
140	                  <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
141	                    <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
142	                    <Badge tone={d.autoRenew ? "green" : "slate"}>
143	                      auto-renew {d.autoRenew ? "on" : "off"}
144	                    </Badge>
145	                    {d.status === "ACTIVE" && (
146	                      <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
147	                    )}
148	                    <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
149	                  </div>
150	                </Link>
151	              );
152	            })}
153	          </div>
154	
155	          <div className="hidden overflow-x-auto lg:block">
156	            <table className="table-shell mt-2 min-w-[760px]">
157	              <thead>
158	                <tr>
159	                  <th>Domain</th>
160	                  <th>Status</th>
161	                  <th>Expires</th>
162	                  <th>DNS</th>
163	                  <th>Price</th>
164	                  <th>Auto-renew</th>
165	                  <th className="text-right">Actions</th>
166	                </tr>
167	              </thead>
168	              <tbody>
169	                {domains.map((d) => {
170	                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
171	                  const count = recordCounts.get(d.id);
172	                  return (
173	                    <tr key={d.id}>
174	                      <td>
175	                        <Link
176	                          href={`/dashboard/domains/${d.id}`}
177	                          className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
178	                        >
179	                          {d.name}
180	                        </Link>
181	                      </td>
182	                      <td>
183	                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
184	                      </td>
185	                      <td>
186	                        {d.expiresAt ? (
187	                          <div className="flex flex-col">
188	                            <span className="text-sm text-slate-300">
189	                              {d.expiresAt.toISOString().slice(0, 10)}
190	                            </span>
191	                            <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
192	                              {expiryLabel(d.expiresAt)}
193	                            </span>
194	                          </div>
195	                        ) : (
196	                          <span className="text-slate-500">—</span>
197	                        )}
198	                      </td>
199	                      <td className="text-slate-400">
200	                        {d.status !== "ACTIVE"
201	                          ? "—"
202	                          : count === null || count === undefined
203	                            ? "—"
204	                            : `${count} record${count === 1 ? "" : "s"}`}
205	                      </td>
206	                      <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
207	                      <td>
208	                        <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
209	                      </td>
210	                      <td className="text-right">
211	                        <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
212	                          Manage
213	                        </Link>
214	                      </td>
215	                    </tr>
216	                  );
217	                })}
218	              </tbody>
219	            </table>
220	          </div>
221	        </div>
222	      )}
223	    </div>
224	  );
225	}
