1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { useActionState } from "react";
5	import { orderServer } from "@/lib/actions";
6	import { VPS_TERMS, vpsTermPriceCents, vpsEffectiveMonthly } from "@/lib/billing-terms";
7	
8	type Plan = {
9	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
10	  bandwidthTB: number; priceCents: number; storageTier: string;
11	};
12	type Image = {
13	  id: string; slug: string; name: string; category: string; family: string;
14	  version: string; logo: string; minRamMB: number; minDiskGB: number;
15	  licenseRequired: boolean; featured: boolean;
16	};
17	type NodeOpt = { id: string; name: string; publicIp: string };
18	
19	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
20	const CATS = [
21	  { key: "PLAIN_OS", label: "Plain OS" },
22	  { key: "CONTROL_PANEL", label: "Control panel" },
23	  { key: "APPLICATION", label: "Applications" },
24	] as const;
25	
26	function LogoChip({ image }: { image: Image }) {
27	  const glyph: Record<string, string> = {
28	    ubuntu: "🟠", debian: "🌀", almalinux: "🐧", rocky: "⛰️", cpanel: "🔶", plesk: "🟦",
29	    webmin: "🧰", cyberpanel: "🛡️", aapanel: "🅰️", hestiacp: "🌿", cloudpanel: "☁️",
30	    docker: "🐳", wordpress: "🅦", lamp: "💡", nodejs: "🟩", nextcloud: "🔷", minecraft: "⛏️",
31	    caddy: "🔒", wireguard: "🛡️", openvpn: "🔐", vaultwarden: "🔑", pihole: "🕳️", uptimekuma: "📈",
32	    gitea: "🍵", jellyfin: "🎬", valheim: "🪓", rust: "🔩", palworld: "🐾", cs2: "🔫", terraria: "🌳",
33	  };
34	  return (
35	    <span className="flex h-8 w-8 items-center justify-center rounded-lg border border-white/10 bg-white/[0.05] text-base">
36	      {glyph[image.logo] ?? image.name.charAt(0)}
37	    </span>
38	  );
39	}
40	
41	function Stepper({ step, steps }: { step: number; steps: string[] }) {
42	  return (
43	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
44	      {steps.map((s, i) => (
45	        <div key={s} className="flex items-center gap-2">
46	          <span
47	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
48	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
49	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
50	                  : "border-white/10 text-slate-500"
51	            }`}
52	          >
53	            {i < step ? "✓" : i + 1}
54	          </span>
55	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
56	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
57	        </div>
58	      ))}
59	    </div>
60	  );
61	}
62	
63	export function DeployWizard({
64	  plans, images, nodes, sshKeys, isAdmin, balanceCents,
65	}: {
66	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
67	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
68	}) {
69	  const [state, action, pending] = useActionState(orderServer, {} as { error?: string });
70	  const multiNode = nodes.length > 1;
71	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
72	  const [step, setStep] = useState(0);
73	
74	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
75	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
