1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { resizeServer } from "@/lib/actions-server";
5	import { fmtMoney } from "@/components/ui/primitives";
6	
7	type PlanRow = {
8	  id: string;
9	  name: string;
10	  cpuCores: number;
11	  ramMB: number;
12	  diskGB: number;
13	  bandwidthTB: number;
14	  priceCents: number;
15	};
16	
17	export function ResizePicker({
18	  serverId,
19	  currentPlanId,
20	  currentDiskGB,
21	  plans,
22	  disabled,
23	}: {
24	  serverId: string;
25	  currentPlanId: string;
26	  currentDiskGB: number;
27	  plans: PlanRow[];
28	  disabled?: boolean;
29	}) {
30	  const [selected, setSelected] = useState<string | null>(null);
31	  const [error, setError] = useState<string | null>(null);
32	  const [pending, start] = useTransition();
33	  const target = plans.find((p) => p.id === selected);
34	
35	  return (
36	    <div className="space-y-5">
37	      {error && (
38	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
39	          {error}
40	        </div>
41	      )}
42	      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
43	        {plans.map((p) => {
44	          const current = p.id === currentPlanId;
45	          const tooSmall = p.diskGB < currentDiskGB;
46	          const active = selected === p.id;
47	          return (
48	            <button
49	              key={p.id}
50	              type="button"
51	              disabled={current || tooSmall || pending || disabled}
52	              title={
53	                tooSmall
54	                  ? `Disk can only grow — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
55	                  : undefined
56	              }
57	              onClick={() => setSelected(active ? null : p.id)}
58	              className={`card p-4 text-left transition-all ${
59	                current
60	                  ? "border-brand-400/60 ring-1 ring-brand-400/60"
61	                  : tooSmall
62	                    ? "cursor-not-allowed opacity-40"
63	                    : active
64	                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
65	                      : "cursor-pointer hover:border-white/20"
66	              }`}
67	            >
68	              <div className="flex items-baseline justify-between">
69	                <span className="font-semibold">{p.name}</span>
70	                <span className="text-lg font-bold">{fmtMoney(p.priceCents)}<span className="text-xs font-normal text-slate-400">/mo</span></span>
71	              </div>
72	              <p className="mt-1 text-sm text-slate-400">
73	                {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
74	              </p>
75	              {current && <p className="mt-2 text-xs font-semibold text-brand-300">Current plan</p>}
76	              {tooSmall && <p className="mt-2 text-xs text-slate-500">Smaller disk — unavailable</p>}
77	            </button>
78	          );
79	        })}
80	      </div>
81	
82	      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
83	        <p className="text-xs text-slate-400">
84	          Resizing requires a power cycle. The new price applies at your next renewal.
85	        </p>
86	        <button
87	          className="btn-primary"
88	          disabled={!target || pending || disabled}
89	          onClick={() => {
90	            if (!target) return;
91	            if (
92	              !window.confirm(
93	                `Resize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)? The server will be power-cycled.`
94	              )
95	            )
96	              return;
97	            start(async () => {
98	              setError(null);
99	              const res = await resizeServer(serverId, target.id);
100	              if (res?.error) setError(res.error);
101	              else setSelected(null);
102	            });
103	          }}
104	        >
105	          {pending ? "Resizing…" : target ? `Resize to ${target.name}` : "Select a plan"}
106	        </button>
107	      </div>
108	    </div>
109	  );
110	}
