41	export function AddFunds() {
42	  const [amount, setAmount] = useState<string>("25");
43	  const [busy, setBusy] = useState(false);
44	  const [error, setError] = useState<string | null>(null);
45	  const [demoMode, setDemoMode] = useState(false);
46	
47	  if (demoMode) return <DemoTopUp />;
48	
49	  const checkout = async () => {
50	    setBusy(true);
51	    setError(null);
52	    try {
53	      const res = await fetch("/api/stripe/checkout", {
54	        method: "POST",
55	        headers: { "Content-Type": "application/json" },
56	        body: JSON.stringify({ amount: Number(amount) }),
57	      });
58	      const json: { url?: string; error?: string } = await res.json().catch(() => ({}));
59	      if (json.url) {
60	        window.location.href = json.url;
61	        return;
62	      }
63	      const msg = json.error ?? "Checkout failed — try again.";
64	      if (msg.toLowerCase().includes("not configured")) {
65	        setDemoMode(true);
66	      } else {
67	        setError(msg);
68	      }
69	    } catch {
70	      setError("Network error — try again.");
71	    }
72	    setBusy(false);
73	  };
74	
75	  const n = Number(amount);
76	  const valid = Number.isFinite(n) && n >= 5 && n <= 5000;
77	
78	  return (
79	    <div>
80	      <div className="flex flex-wrap items-end gap-3">
81	        <div>
82	          <label className="label">Amount (USD)</label>
83	          <div className="flex items-center gap-2">
84	            {PRESETS.map((p) => (
85	              <button
86	                key={p}
87	                type="button"
88	                onClick={() => setAmount(String(p))}
89	                className={`rounded-lg border px-2.5 py-1.5 text-xs font-semibold transition-colors ${
90	                  amount === String(p)
91	                    ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
92	                    : "border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"
93	                }`}
94	              >
95	                ${p}
96	              </button>
97	            ))}
98	            <input
99	              className="input w-28"
100	              type="number"
101	              min={5}
102	              max={5000}
103	              value={amount}
104	              onChange={(e) => setAmount(e.target.value)}
105	            />
106	          </div>
107	        </div>
108	        <button className="btn-primary" onClick={() => void checkout()} disabled={busy || !valid}>
109	          {busy ? "Redirecting…" : "Add funds"}
110	        </button>
111	      </div>
112	      {!valid && amount !== "" && (
113	        <p className="mt-2 text-xs text-amber-300">Amount must be between $5 and $5000.</p>
114	      )}
115	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
116	      <p className="mt-2 text-xs text-slate-500">Secure card checkout powered by Stripe.</p>
117	    </div>
118	  );
119	}
