1	import Link from "next/link";
2	import { requireAdmin } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { ServerStatus } from "@prisma/client";
5	import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
6	import { SuspendServerButton } from "@/components/AdminControls";
7	import { AutoRefresh } from "@/components/AutoRefresh";
8	
9	export const dynamic = "force-dynamic";
10	
11	const STATUSES = Object.values(ServerStatus);
12	const TRANSITIONAL: ServerStatus[] = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];
13	
14	export default async function AdminServers({
15	  searchParams,
16	}: {
17	  searchParams: Promise<{ status?: string }>;
18	}) {
19	  await requireAdmin();
20	  const { status } = await searchParams;
21	  const statusFilter = STATUSES.includes(status as ServerStatus) ? (status as ServerStatus) : undefined;
22	
23	  const [servers, counts] = await Promise.all([
24	    db.server.findMany({
25	      where: statusFilter ? { status: statusFilter } : undefined,
26	      include: {
27	        user: { select: { id: true, email: true } },
28	        plan: { select: { name: true, priceCents: true } },
29	      },
30	      orderBy: { createdAt: "desc" },
31	    }),
32	    db.server.groupBy({ by: ["status"], _count: true }),
33	  ]);
34	
35	  const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
36	  const total = counts.reduce((n, c) => n + c._count, 0);
37	  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));
38	
39	  return (
40	    <div className="space-y-6">
41	      {anyTransitional && <AutoRefresh />}
42	      <PageHeader title="Server fleet" sub={`${total} server${total === 1 ? "" : "s"} across all clients.`} />
43	
44	      {/* Status filter chips */}
45	      <div className="flex flex-wrap items-center gap-2">
46	        <Link
47	          href="/admin/servers"
48	          className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
49	            !statusFilter
50	              ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
51	              : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
52	          }`}
53	        >
54	          All · {total}
55	        </Link>
56	        {STATUSES.filter((s) => countByStatus.has(s)).map((s) => (
57	          <Link
58	            key={s}
59	            href={`/admin/servers?status=${s}`}
60	            className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
61	              statusFilter === s
62	                ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
63	                : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
64	            }`}
65	          >
66	            {s.toLowerCase().replace(/_/g, " ")} · {countByStatus.get(s)}
67	          </Link>
68	        ))}
69	      </div>
70	
71	      <div className="card overflow-x-auto p-0">
72	        <table className="table-shell">
73	          <thead>
74	            <tr>
75	              <th>Hostname</th>
76	              <th>Owner</th>
77	              <th>Plan</th>
78	              <th>VMID</th>
79	              <th>SSH endpoint</th>
80	              <th>Status</th>
81	              <th>Expires</th>
82	              <th className="text-right">Actions</th>
83	            </tr>
84	          </thead>
85	          <tbody>
86	            {servers.length === 0 && (
87	              <tr>
88	                <td colSpan={8} className="py-10 text-center text-slate-500">
89	                  No servers{statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.
90	                </td>
91	              </tr>
92	            )}
93	            {servers.map((s) => (
94	              <tr key={s.id}>
95	                <td>
96	                  <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
97	                    {s.hostname}
98	                  </Link>
99	                  {s.isFree && (
100	                    <span className="ml-2">
101	                      <Badge tone="green">free</Badge>
102	                    </span>
103	                  )}
104	                </td>
105	                <td>
106	                  <Link href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
107	                    {s.user.email}
108	                  </Link>
109	                </td>
110	                <td>
111	                  {s.plan.name}
112	                  {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(s.plan.priceCents)}/mo</span>}
113	                </td>
114	                <td className="font-mono text-xs">{s.vmid ?? "—"}</td>
115	                <td className="font-mono text-xs">
116	                  {s.ipAddress ? `${s.ipAddress}${s.sshPort ? `:${s.sshPort}` : ""}` : "—"}
117	                </td>
118	                <td>
119	                  <StatusDot status={s.status} />
120	                </td>
121	                <td className="text-xs">
122	                  {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
123	                </td>
124	                <td className="text-right">
125	                  {s.status !== "DELETING" && (
126	                    <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
127	                  )}
128	                </td>
129	              </tr>
130	            ))}
131	          </tbody>
132	        </table>
133	      </div>
134	    </div>
135	  );
136	}
