159	export function fmtBytes(b: number): string {
160	  if (!b || b <= 0) return "0 B";
161	  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
162	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
163	  return `${(b / 1024 ** i).toFixed(1)} ${units[i]}`;
164	}
165	
166	export function fmtMoney(cents: number): string {
167	  return `$${(cents / 100).toFixed(2)}`;
168	}
169	
170	export function timeAgo(d: Date): string {
171	  const s = Math.floor((Date.now() - d.getTime()) / 1000);
172	  if (s < 60) return `${s}s ago`;
173	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
174	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
175	  return `${Math.floor(s / 86400)}d ago`;
176	}
