7	/* ------------------------------------------------------------------ */
8	/*  Looping "instant deploy" terminal                                  */
9	/* ------------------------------------------------------------------ */
10	
11	const COMMAND = "nxeon deploy --plan pro --os ubuntu";
12	
13	type OutLine = { text: string; tone: "muted" | "ok" | "info" | "accent" };
14	
15	const OUTPUT: OutLine[] = [
16	  { text: "→ Allocating NVMe volume on ZFS mirror…", tone: "muted" },
17	  { text: "→ Cloning Ubuntu 24.04 template (cloud-init)…", tone: "muted" },
18	  { text: "→ Attaching dedicated IPv4 · configuring firewall…", tone: "muted" },
19	  { text: "✓ Server web-prod-01 is live in 47s", tone: "ok" },
20	  { text: "  ssh root@51.79.162.96 -p 20114", tone: "accent" },
21	];
22	
23	function DeployTerminal() {
24	  const [typed, setTyped] = useState("");
25	  const [lines, setLines] = useState<OutLine[]>([]);
26	  const [phase, setPhase] = useState<"typing" | "running" | "done">("typing");
27	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
28	
29	  useEffect(() => {
30	    let cancelled = false;
31	    const wait = (ms: number) =>
32	      new Promise<void>((res) => {
33	        const t = setTimeout(res, ms);
34	        timers.current.push(t);
35	      });
36	
37	    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
38	
39	    async function loop() {
40	      while (!cancelled) {
41	        // reset
42	        setTyped("");
43	        setLines([]);
44	        setPhase("typing");
45	        await wait(600);
46	
47	        if (reduce) {
48	          setTyped(COMMAND);
49	          setLines(OUTPUT);
50	          setPhase("done");
51	          await wait(6000);
52	          continue;
53	        }
54	
55	        // type the command
56	        for (let i = 1; i <= COMMAND.length; i++) {
57	          if (cancelled) return;
58	          setTyped(COMMAND.slice(0, i));
59	          await wait(38 + (COMMAND[i - 1] === " " ? 40 : 0));
60	        }
61	        await wait(400);
62	        setPhase("running");
63	
64	        // stream output
65	        for (const line of OUTPUT) {
66	          if (cancelled) return;
67	          setLines((prev) => [...prev, line]);
68	          await wait(line.tone === "ok" ? 720 : 620);
69	        }
70	        setPhase("done");
71	        await wait(3400);
72	      }
73	    }
74	    loop();
75	
76	    return () => {
77	      cancelled = true;
78	      timers.current.forEach(clearTimeout);
79	      timers.current = [];
80	    };
81	  }, []);
82	
83	  const toneClass: Record<OutLine["tone"], string> = {
84	    muted: "text-slate-400",
85	    ok: "text-emerald-300 font-medium",
86	    info: "text-brand-300",
87	    accent: "text-accent-cyan",
88	  };
89	
90	  return (
91	    <div className="nx-terminal glass relative overflow-hidden shadow-2xl">
92	      <div className="pointer-events-none absolute -inset-8 rounded-[2.5rem] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 blur-2xl" />
93	      <div className="relative">
94	        {/* window chrome */}
95	        <div className="flex items-center gap-2 border-b border-white/[0.06] px-4 py-3">
96	          <span className="h-3 w-3 rounded-full bg-red-400/70" />
97	          <span className="h-3 w-3 rounded-full bg-amber-400/70" />
98	          <span className="h-3 w-3 rounded-full bg-emerald-400/70" />
99	          <span className="ml-3 flex items-center gap-2 rounded-md border border-white/10 bg-white/[0.04] px-3 py-1 text-[11px] text-slate-500">
100	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
101	            nxeon@cloud — deploy
102	          </span>
103	        </div>
104	
105	        <div className="min-h-[248px] px-4 py-4 font-mono text-[12.5px] leading-relaxed sm:text-[13px]">
106	          <div className="flex flex-wrap items-baseline gap-x-2">
107	            <span className="text-emerald-400">$</span>
108	            <span className="break-all text-slate-100">
109	              {typed}
110	              {phase === "typing" && <span className="nx-caret">▋</span>}
111	            </span>
112	          </div>
113	
114	          <div className="mt-3 space-y-1.5">
115	            {lines.map((l, i) => (
116	              <div key={i} className={`nx-line ${toneClass[l.tone]}`}>
117	                {l.text}
118	              </div>
119	            ))}
120	          </div>
121	
122	          {phase === "done" && (
123	            <div className="nx-line mt-4 inline-flex items-center gap-2 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-2.5 py-1 text-[11px] font-medium text-emerald-300">
124	              <span className="flex h-3.5 w-3.5 items-center justify-center">
125	                <IconCheck size={11} />
126	              </span>
127	              Deployment complete
128	            </div>
129	          )}
130	        </div>
131	      </div>
132	    </div>
133	  );
134	}
