3	import { useState, useTransition } from "react";
4	import { createSnapshot, deleteSnapshot, rollbackSnapshot } from "@/lib/actions-server";
5	
6	export function CreateSnapshotForm({ serverId, disabled }: { serverId: string; disabled?: boolean }) {
7	  const [name, setName] = useState("");
8	  const [error, setError] = useState<string | null>(null);
9	  const [pending, start] = useTransition();
10	
11	  return (
12	    <div>
13	      <div className="flex flex-wrap items-end gap-3">
14	        <div>
15	          <label className="label">Snapshot name</label>
16	          <input
17	            className="input w-56"
18	            value={name}
19	            onChange={(e) => setName(e.target.value)}
20	            placeholder="before_upgrade"
21	            maxLength={40}
22	            disabled={pending || disabled}
23	          />
24	        </div>
25	        <button
26	          className="btn-primary"
27	          disabled={pending || disabled || name.trim().length < 2}
28	          onClick={() =>
29	            start(async () => {
30	              setError(null);
31	              const res = await createSnapshot(serverId, name.trim());
32	              if (res?.error) setError(res.error);
33	              else setName("");
34	            })
35	          }
36	        >
37	          {pending ? "Creating…" : "Create snapshot"}
38	        </button>
39	      </div>
40	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
41	      <p className="mt-2 text-xs text-slate-500">Letters, digits and underscores only.</p>
42	    </div>
43	  );
44	}
45	
46	export function SnapshotActions({
47	  serverId,
48	  name,
49	  disabled,
50	}: {
51	  serverId: string;
52	  name: string;
53	  disabled?: boolean;
54	}) {
55	  const [error, setError] = useState<string | null>(null);
56	  const [pending, start] = useTransition();
57	
58	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg: string) => {
59	    if (!window.confirm(confirmMsg)) return;
60	    start(async () => {
61	      setError(null);
62	      const res = await fn();
63	      if (res?.error) setError(res.error);
64	    });
65	  };
66	
67	  return (
68	    <div className="flex items-center justify-end gap-2">
69	      {error && <span className="text-xs text-red-400">{error}</span>}
70	      <button
71	        className="btn-secondary px-3 py-1 text-xs"
72	        disabled={pending || disabled}
73	        onClick={() =>
74	          run(
75	            () => rollbackSnapshot(serverId, name),
76	            `Roll back to snapshot "${name}"? All changes made after this snapshot will be lost.`
77	          )
78	        }
79	      >
80	        Rollback
81	      </button>
82	      <button
83	        className="btn-danger px-3 py-1 text-xs"
84	        disabled={pending || disabled}
85	        onClick={() =>
86	          run(
87	            () => deleteSnapshot(serverId, name),
88	            `Delete snapshot "${name}"? This cannot be undone.`
89	          )
90	        }
91	      >
92	        Delete
93	      </button>
94	    </div>
95	  );
96	}
