15	export default async function AdminAnalytics() {
16	  await requireAdmin();
17	
18	  const now = new Date();
19	  const since30d = new Date(Date.now() - 30 * 86400_000);
20	  const sixMonthsAgo = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 5, 1));
21	  const twelveWeeksAgo = new Date(Date.now() - 12 * 7 * 86400_000);
22	
23	  const [charges6mo, signups, activeServers, deletions30d, spend30d, firstUser] = await Promise.all([
24	    db.walletTransaction.findMany({
25	      where: { amountCents: { lt: 0 }, createdAt: { gte: sixMonthsAgo } },
26	      select: { amountCents: true, createdAt: true },
27	    }),
28	    db.user.findMany({
29	      where: { createdAt: { gte: twelveWeeksAgo } },
30	      select: { createdAt: true },
31	    }),
32	    db.server.findMany({
33	      where: { status: { notIn: ["DELETING"] } },
34	      include: { plan: { select: { id: true, name: true, priceCents: true } }, user: { select: { id: true, email: true, name: true } } },
35	    }),
36	    db.auditLog.count({ where: { action: "server.delete", createdAt: { gte: since30d } } }),
37	    db.walletTransaction.aggregate({
38	      where: { amountCents: { lt: 0 }, createdAt: { gte: since30d } },
39	      _sum: { amountCents: true },
40	    }),
